export default async function UserDashboard() {
  let preferences;

  try {
    // Fetch with no-store to ensure fresh data on every request
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error(`Failed to fetch: ${res.status}`);
    }

    preferences = await res.json();
  } catch {
    // Return default/fallback preferences if fetch fails
    preferences = { 
      theme: 'system', 
      notifications: true, 
      status: 'active' 
    };
  }

  return (
    <div className="p-4 border rounded shadow-sm bg-white">
      <h2 className="text-xl font-bold mb-4">User Dashboard</h2>
      <div className="space-y-2">
        <div className="grid grid-cols-2 gap-2 text-sm">
          <div className="font-semibold">Theme:</div>
          <div>{preferences.theme}</div>
          <div className="font-semibold">Notifications:</div>
          <div>{preferences.notifications ? 'Enabled' : 'Disabled'}</div>
          <div className="font-semibold">Status:</div>
          <div>{preferences.status}</div>
        </div>
        <p className="text-xs text-gray-400 mt-4 italic">
          Data fetched dynamically per request.
        </p>
      </div>
    </div>
  );
}

